// Distance calculation using Haversine formula
// Returns distance in kilometers between two coordinates

const EARTH_RADIUS_KM = 6371;

function toRadians(degrees) {
  return degrees * (Math.PI / 180);
}

/**
 * Calculate distance between two points using Haversine formula
 * @param {number} lat1 - Latitude of first point
 * @param {number} lng1 - Longitude of first point
 * @param {number} lat2 - Latitude of second point
 * @param {number} lng2 - Longitude of second point
 * @returns {number} Distance in kilometers
 */
export function calculateDistance(lat1, lng1, lat2, lng2) {
  const dLat = toRadians(lat2 - lat1);
  const dLng = toRadians(lng2 - lng1);

  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRadians(lat1)) * Math.cos(toRadians(lat2)) *
    Math.sin(dLng / 2) * Math.sin(dLng / 2);

  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

  return EARTH_RADIUS_KM * c;
}

/**
 * Check if a restaurant is within the delivery radius
 * @param {object} userLocation - User's location {lat, lng}
 * @param {object} restaurantLocation - Restaurant's location {lat, lng}
 * @param {number} radiusKm - Radius in kilometers (default 4km)
 * @returns {boolean} True if within radius
 */
export function isWithinRadius(userLocation, restaurantLocation, radiusKm = 4) {
  if (!userLocation || !userLocation.lat || !userLocation.lng) return false;
  if (!restaurantLocation || !restaurantLocation.lat || !restaurantLocation.lng) return false;

  const distance = calculateDistance(
    userLocation.lat,
    userLocation.lng,
    restaurantLocation.lat,
    restaurantLocation.lng
  );

  return distance <= radiusKm;
}

/**
 * Filter restaurants by distance radius
 * @param {array} restaurants - Array of restaurant objects
 * @param {object} userLocation - User's location {lat, lng}
 * @param {number} radiusKm - Radius in kilometers (default 4km)
 * @returns {array} Restaurants within radius
 */
export function filterRestaurantsByRadius(restaurants, userLocation, radiusKm = 4) {
  if (!userLocation || !userLocation.lat || !userLocation.lng) return restaurants;

  return restaurants.filter(restaurant => {
    if (!restaurant.lat || !restaurant.lng) return false;
    
    const distance = calculateDistance(
      userLocation.lat,
      userLocation.lng,
      restaurant.lat,
      restaurant.lng
    );

    return distance <= radiusKm;
  }).map(restaurant => ({
    ...restaurant,
    distance: calculateDistance(
      userLocation.lat,
      userLocation.lng,
      restaurant.lat,
      restaurant.lng
    )
  }));
}

export default { calculateDistance, isWithinRadius, filterRestaurantsByRadius };
